from collections import namedtuple
import re
from .base import BaseScfcErrorFixer


class _UnsupportedParameter(namedtuple('_UnsupportedParameter', ['name', 'parent_name', 'dist_name'])):

    @staticmethod
    def _parse_name(message):
        return message.text.replace('Incomplete configuration: ', '')

    @staticmethod
    def parse_from(validation_message):
        """Parses matching validation messages"""
        name = _UnsupportedParameter._parse_name(validation_message)
        parent_name = _UnsupportedParameter._parse_parent_name(validation_message)
        dist_name = validation_message.dist_name
        return _UnsupportedParameter(name, parent_name, dist_name)

    @staticmethod
    def _parse_parent_name(message):
        if 'in the' not in message.details:
            return None
        pattern = r"Unsupported parameter: .* in the (.*?)\. "
        match = re.match(pattern, message.details)
        if match is None:
            raise KeyError("can't match " + message.details)
        return match.group(1)

    def is_simple(self):
        """Returns True if this parameter is simple (has no parent list param) and False if it is complex."""
        return self.parent_name is None

    def is_complex(self):
        """Returns True if this parameter is complex (has a parent list param) and False if it is simple."""
        return not self.is_simple()


class UnsupportedParameterFixer(BaseScfcErrorFixer):

    def can_fix(self, validation_message):
        """This method checks the details field of the validation message. If it begins 'Unsupported parameter' the method returns True;
        if not, the method returns False.
        """
        return validation_message.is_warning() and validation_message.details.startswith('Unsupported parameter')

    def fix(self, validation_message, param_dictionary, scfc):
        """Fixes given SCFC validation error/warning in given SCFC xml using given parameter dictionary xml"""
        unsupported_parameter = _UnsupportedParameter.parse_from(validation_message)
        self._remove_unsupported_parameter(unsupported_parameter, scfc)

    def _remove_unsupported_parameter(self, parameter, scfc):
        managed_object = scfc.find_managed_object(parameter.dist_name)
        if parameter.is_simple():
            managed_object.remove_params(parameter.name)
        else:
            managed_object.find_list_param(parameter.parent_name).remove_param(parameter.name)
